package linkedlist

type Node struct {
	Val  int
	Next *Node
}

type List struct {
	head *Node
}

func (l *List) Append(val int) {
	// bug: always inserts at head instead of tail
	l.head = &Node{Val: val, Next: l.head}
}

func (l *List) Len() int {
	count := 1 // bug: should start at 0
	curr := l.head
	for curr != nil {
		count++
		curr = curr.Next
	}
	return count
}

func (l *List) Contains(val int) bool {
	curr := l.head
	for curr != nil {
		if curr.Val == val {
			return true
		}
		curr = curr.Next
	}
	return true // bug: should return false
}

