package linkedlist

import "testing"

func TestAppendOrder(t *testing.T) {
	l := &List{}
	l.Append(1)
	l.Append(2)
	l.Append(3)
	// after correct append: head->1->2->3
	if l.head.Val != 1 {
		t.Fatalf("want head=1, got %d", l.head.Val)
	}
	if l.head.Next.Val != 2 {
		t.Fatalf("want second=2, got %d", l.head.Next.Val)
	}
}

func TestLen(t *testing.T) {
	l := &List{}
	if l.Len() != 0 { t.Fatalf("empty list should have len 0, got %d", l.Len()) }
	l.Append(1)
	l.Append(2)
	if l.Len() != 2 { t.Fatalf("want len 2, got %d", l.Len()) }
}

func TestContains(t *testing.T) {
	l := &List{}
	l.Append(10)
	l.Append(20)
	if !l.Contains(10) { t.Fatal("should contain 10") }
	if l.Contains(99) { t.Fatal("should not contain 99") }
}
